const ELEMENT_PROP_KEYS = new Set(["theme","lead","brand","slot","end","note","stagger","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  lead: "A launch film for",
  brand: "remocn",
  slot: "yourProduct",
  end: ".",
  note: "Swap one prop. The film is yours.",
  stagger: 3,
  fontFamily: "Lexend",
  scale: 1,
  delay: 0,
  speed: 1,
};

type YourNameHereElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof YourNameHereBase>;

const YourNameHereInner = forwardRef<
  HTMLDivElement,
  YourNameHereElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<YourNameHere>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <YourNameHereBase
          {...(componentProps as unknown as ComponentProps<typeof YourNameHereBase>)}
        />
      </div>
    </Sequence>
  );
});

export const YourNameHere = Interactive.withSchema({
  Component: YourNameHereInner,
  componentName: "<YourNameHere>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
